<section class="page-heading"><div><p class="eyebrow">Evento APC</p><h1><?=e($event['titulo'])?></h1><p><?=e(date('d/m/Y',strtotime($event['data'])))?></p></div><span class="badge status-<?=e($window['state']==='ABERTA'?'aprovado':($window['state']==='AGUARDANDO'?'rascunho':'pendente'))?>"><?=e($windowLabels[$window['state']])?></span></section>
